(function(){'use strict';
/* STAGING LOCALE BUILD (sk) — generated by scripts/build_locale_staging.py from assets/growth/tools.js.
 * Only string literals and display formatting differ. Formulas, weights, thresholds, clamping and toFixed() rounding are
 * unchanged; fx() formats the already-rounded value with Intl.NumberFormat. Parity: scripts/locale_tools_parity.js. */
const LOC="sk-SK";
const fx=(n,d)=>new Intl.NumberFormat(LOC,{minimumFractionDigits:d,maximumFractionDigits:d}).format(Number(n.toFixed(d)));
const PLC=n=>(n===1?"{n} vybraný signál":(n>=2&&n<=4)?"{n} vybrané signály":"{n} vybraných signálov").replace('{n}',String(n));
const VCS_LINK="„{phrase}“ vo VC hovorí";

const $=id=>document.getElementById(id), num=id=>{const el=$(id);if(!el)return 0;let v=Number(el.value);if(!Number.isFinite(v))return 0;if(el.min!==''&&Number.isFinite(Number(el.min)))v=Math.max(Number(el.min),v);if(el.max!==''&&Number.isFinite(Number(el.max)))v=Math.min(Number(el.max),v);return v};
const money=(n)=>new Intl.NumberFormat(LOC,{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number.isFinite(n)?n:0);
const pct=(n)=>fx(Number.isFinite(n)?n:0,1)+'\u00a0%';
function event(name,props={}){try{if(window.posthog&&typeof window.posthog.capture==='function')window.posthog.capture(name,props);if(typeof window.gtag==='function')window.gtag('event',name,props)}catch(e){}}
function bindCalculate(id,fn){const b=$(id);if(!b)return;b.addEventListener('click',()=>{fn();event('tfg_tool_completed',{tool_slug:document.body.dataset.tool||'unknown'})});}
function set(id,value){const el=$(id);if(el)el.textContent=String(value)}
function copyText(txt,button){if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(txt).then(()=>{if(button)button.textContent="Skopírované ✓";event('tfg_tool_result_copied',{tool_slug:document.body.dataset.tool||'unknown'})}).catch(()=>fallback())}else fallback();function fallback(){let ta=document.createElement('textarea');ta.value=txt;ta.style.position='fixed';ta.style.top='-9999px';document.body.appendChild(ta);ta.select();try{document.execCommand('copy');if(button)button.textContent="Skopírované ✓";event('tfg_tool_result_copied',{tool_slug:document.body.dataset.tool||'unknown'})}catch(e){if(button)button.textContent="Označte text a skopírujte ho"}ta.remove()}}
const signalItems=[
{key:'next',label:"Navrhne konkrétne ďalšie stretnutie alebo termín",weight:4,group:'action'},
{key:'partner',label:"Predstaví vás ďalšiemu partnerovi alebo človeku, ktorý rozhoduje",weight:4,group:'action'},
{key:'diligence',label:"Vyžiada si konkrétne dokumenty na due diligence alebo referencie zákazníkov",weight:3,group:'action'},
{key:'champion',label:"Jasne vysvetlí, ako u nich funguje interný rozhodovací proces",weight:2,group:'action'},
{key:'question',label:"Kladie konkrétne doplňujúce otázky o vašom biznise",weight:1,group:'interest'},
{key:'polite',label:"Povie „zaujímavé, dajte nám vedieť“ bez ďalšieho kroku",weight:-2,group:'caution'},
{key:'noresponse',label:"Nedodržal dohodnutý termín odpovede a neozval sa",weight:-2,group:'caution'},
{key:'wrong',label:"Povie, že fáza, sektor, geografia alebo výška investície nesedí",weight:-4,group:'caution'},
];
function initSignals(){const wrap=$('signals-list');if(!wrap)return;signalItems.forEach(s=>{let lab=document.createElement('label');lab.className='formcheck';let ch=document.createElement('input');ch.type='checkbox';ch.name='signal';ch.value=s.key;lab.appendChild(ch);lab.append(document.createTextNode(s.label));wrap.appendChild(lab)});bindCalculate('signals-calculate',()=>{const chosen=[...document.querySelectorAll('input[name="signal"]:checked')].map(x=>signalItems.find(s=>s.key===x.value));const score=chosen.reduce((sum,x)=>sum+x.weight,0);const actions=chosen.filter(x=>x.group==='action').length;let status="Nedostatočný signál",desc="Zatiaľ nemáte dosť dôkazov o konkrétnom procese. Opýtajte sa, či ste pre investora vhodní a aký bude ďalší rozhodovací bod.",next="Pošlite krátky, konkrétny follow-up s návrhom vhodného ďalšieho kroku a pokračujte v rozhovoroch s ďalšími investormi.";if(chosen.some(x=>x.key==='wrong')){status="Pravdepodobne štrukturálny nesúlad";desc="Výslovný nesúlad vo fáze, investičnej téze, geografii alebo výške investície má väčšiu váhu než priateľský tón.";next="Poďakujte, opýtajte sa, či nepoznajú vhodnejšieho kolegu alebo fond, a vyraďte príležitosť z aktívnej pipeline."}else if(score>=5&&actions>=2){status="Významné signály procesu";desc="Viacero konkrétnych krokov naznačuje skutočný hodnotiaci proces; investíciu však stále nezaručujú.";next="Písomne si potvrďte, kto je za čo zodpovedný, aké materiály a termíny platia. Pokračujte aj v ostatných rozhovoroch."}else if(score>=2&&actions>=1){status="Prvé známky záujmu";desc="Konkrétny krok vypovedá viac než komplimenty, proces však zatiaľ nie je presvedčivý.";next="Splňte, o čo vás požiadali, a opýtajte sa, aké bude ďalšie rozhodnutie a kedy."}else if(score<0){status="Slabá alebo klesajúca dynamika";desc="Zdvorilý záujem bez činov alebo nedodržané sľuby si vyžadujú vyjasnenie, nie optimistický výklad.";next="Pošlite jednu podstatnú novinku a požiadajte o jasné áno/nie, či pokračovať; nevymýšľajte si termíny."}const rel=$('signal-related');if(rel){const has=k=>chosen.some(x=>x.key===k);const id=has('wrong')?'not-right-fit':has('noresponse')?'investor-ghosting':has('partner')?'partner-introduction':has('next')?'second-meeting':has('polite')?'keep-in-touch':null;rel.textContent='';if(id)rel.appendChild(vcSaysLink(id,"Súvisiaci návod k fráze: "));else{const a=document.createElement('a');a.href="/sk/vc-says";a.textContent="Prezrite si VC hovorí: bežné frázy investorov a ako na ne odpovedať";rel.appendChild(a)}}set('signal-status',status);set('signal-desc',desc);set('signal-next',next);set('signal-count',PLC(chosen.length));$('signal-meter').style.width=Math.max(5,Math.min(100,(score+8)*5))+'%';});}
function initPipeline(){if(!$('pipeline-calculate'))return;const run=()=>{const leads=num('pipe-leads'), r1=num('pipe-r1')/100,r2=num('pipe-r2')/100,r3=num('pipe-r3')/100,r4=num('pipe-r4')/100;let first=leads*r1,second=first*r2,terms=second*r3,closed=terms*r4;set('pipe-meetings',fx(first,1));set('pipe-deep',fx(second,1));set('pipe-terms',fx(terms,2));set('pipe-closes',fx(closed,2));set('pipe-close-rate',pct(leads>0?closed/leads*100:0));let target=Math.max(.0000001,r1*r2*r3*r4);set('pipe-needed',Math.ceil(1/target).toLocaleString(LOC));set('pipe-note',terms<1?"Pri týchto predpokladoch sa neočakáva ani jeden term sheet. Zlepšite zhodu s investormi, konverzie alebo objem oslovení; výsledky nie sú zaručené.":"Ide o model očakávanej hodnoty, nie o predpoveď skutočných záväzkov. Pri malých číslach sa výsledky môžu výrazne líšiť.");};bindCalculate('pipeline-calculate',run);run();}
function initRunway(){if(!$('runway-calculate'))return;const run=()=>{const cash=num('run-cash'),net=Math.max(0,num('run-expenses')-num('run-revenue')),months=num('run-months'),one=num('run-onetime'),buffer=num('run-buffer')/100,pre=num('run-pre');const core=Math.max(0,net*months+one-cash),raise=core*(1+buffer),post=pre+raise,dil=post>0?raise/post*100:0,existing=net>0?cash/net:Infinity;set('run-net',money(net));set('run-existing',Number.isFinite(existing)?fx(existing,1):"Bez čistého burnu");set('run-raise',money(raise));set('run-dilution',pct(dil));set('run-post',money(post));set('run-pool',money(raise-core));set('run-note',pre<=0?"Na výpočet zjednodušeného riedenia zadajte kladné pre-money ocenenie.":"Iba ilustratívne kolo s pevným ocenením: nezahŕňa opčný pool, SAFE, konvertibilné pôžičky, poplatky ani zmeny burnu. Podmienky obchodu si overte so svojimi poradcami.");};bindCalculate('runway-calculate',run);run();}
const templates={
 meeting:{subject:"Ďakujem za dnešný rozhovor — [názov firmy]",intro:"ďakujem za dnešný rozhovor a za váš pohľad na [téma].",mid:"Ako sme sa dohodli, pošlem vám [sľúbený materiál]. Naša najdôležitejšia novinka: [pokrok].",ask:"Mohli by sme ako ďalší krok naplánovať [konkrétny ďalší krok]?"},
 tooearly:{subject:"Re: [názov firmy] — pokrok k míľniku",intro:"ďakujem za úprimnú spätnú väzbu, že na vaše súčasné investičné kritériá môžeme byť zatiaľ v príliš skorej fáze.",mid:"Od nášho rozhovoru sme pokročili takto: [pokrok]. Sústreďujem sa na míľnik, o ktorom sme hovorili: [míľnik].",ask:"Posunul by nás tento míľnik bližšie k vašej investičnej hranici, alebo je tu iná medzera, ktorú by sme mali riešiť?"},
 quiet:{subject:"Krátka novinka o [názov firmy]",intro:"nadväzujem na náš rozhovor na tému [téma].",mid:"Krátka novinka od nášho posledného rozhovoru: [pokrok].",ask:"Máte ešte záujem v rozhovore pokračovať, alebo sa mám ozvať, keď splníme tento míľnik: [míľnik]? Pomôže mi akákoľvek odpoveď."},
 update:{subject:"[názov firmy] — novinka: [pokrok]",intro:"ešte raz ďakujem za návrh zostať v kontakte po našom rozhovore na tému [téma].",mid:"Najdôležitejší posun od nášho rozhovoru: [pokrok]. Ďalej smerujeme k tomuto míľniku: [míľnik].",ask:"Bolo by pre vás užitočné zostať na našom krátkom zozname investorských noviniek, alebo vás zaujíma nejaká konkrétna metrika?"},
 notfit:{subject:"Re: [názov firmy] — ďakujem",intro:"ďakujem za jasnú odpoveď — oceňujem, že nemusíme hádať.",mid:"Ak máte chvíľu: išlo hlavne o fázu, sektor alebo geografiu? Pomôže mi to zamerať sa na vhodnejších investorov.",ask:"Ak vám napadne fond, ktorý zvyčajne investuje do firiem, ako je tá naša, veľmi ocením tip."},
 nolead:{subject:"[názov firmy] — štruktúra kola",intro:"ďakujem za jasnú informáciu, že podmienkou je pre vás hlavný investor v kole.",mid:"Teraz sa sústreďujeme na získanie hlavného investora. Naša najdôležitejšia novinka: [pokrok].",ask:"Ak získame hlavného investora za podmienok v rozsahu, o ktorom sme hovorili, akú výšku investície by ste zvážili a máte požiadavky na to, kto by mal kolo viesť? Veľmi ocením aj kontakty na fondy, ktoré v našej fáze kolá vedú."},
 cold:{subject:"[názov firmy] — krátky follow-up",intro:"nadväzujem na svoju správu o [názov firmy], ktorá pomáha [zákazník] dosiahnuť [výsledok].",mid:"Jedna dôležitá novinka: [pokrok].",ask:"Spadá to do vášho súčasného investičného zamerania? Ak vám to pomôže, pošlem stručný prehľad."}
};
/* Shared VC Says signal IDs (data/vc_signals.expanded.json). tpl = Follow-up Builder scenario. */
const VC_SAYS={'too-early':{phrase:"Na nás je to zatiaľ priskoro.",tpl:'tooearly'},'not-right-fit':{phrase:"Nezapadá to do našej investičnej stratégie.",tpl:'notfit'},'keep-in-touch':{phrase:"Zostaňme v kontakte.",tpl:'update'},'circle-back-next-quarter':{phrase:"Ozvite sa nám znova budúci štvrťrok.",tpl:'update'},'send-deck':{phrase:"Pošlite mi svoju prezentáciu.",tpl:'meeting'},'second-meeting':{phrase:"Dohodnime si ďalšie stretnutie.",tpl:'meeting'},'partner-introduction':{phrase:"Rád by som vás zoznámil s kolegom z fondu.",tpl:'meeting'},'need-more-traction':{phrase:"Potrebujeme vidieť väčšiu trakciu.",tpl:'tooearly'},'no-lead-investor':{phrase:"Ozvite sa, keď budete mať hlavného investora.",tpl:'nolead'},'investor-ghosting':{phrase:"Žiadna odpoveď ani po dvoch pripomenutiach.",tpl:'quiet'}};
function signalFromQuery(){try{const id=new URLSearchParams(location.search).get('signal');return id&&Object.prototype.hasOwnProperty.call(VC_SAYS,id)?id:null}catch(e){return null}}
function vcSaysLink(id,prefix){const p=document.createElement('span');p.append(document.createTextNode(prefix));const a=document.createElement('a');a.href="/sk/vc-says/"+id;a.textContent=VCS_LINK.replace('{phrase}',VC_SAYS[id].phrase.replace(/[.?!]$/,''));p.appendChild(a);p.append(document.createTextNode('.'));return p}
function clean(str,alt){let x=(str||'').trim().replace(/[\r\n]+/g,' ').slice(0,450);return x||alt}
function initFollowup(){if(!$('followup-calculate'))return;const sig=signalFromQuery();if(sig){const sel=$('follow-type');if(sel&&[...sel.options].some(o=>o.value===VC_SAYS[sig].tpl))sel.value=VC_SAYS[sig].tpl;const note=$('follow-signal-note');if(note){note.textContent='';note.appendChild(vcSaysLink(sig,"Situácia je predvolená podľa záznamu vo VC hovorí: "));note.hidden=false}event('tfg_followup_signal_prefill',{signal_id:sig})}const run=()=>{const type=$('follow-type').value,t=templates[type],company=clean($('follow-company').value,'[názov firmy]'),person=clean($('follow-name').value,'[meno investora]'),topic=clean($('follow-topic').value,"náš biznis"),progress=clean($('follow-progress').value,"[konkrétny, overiteľný pokrok]"),milestone=clean($('follow-milestone').value,"[dohodnutý míľnik]"),next=clean($('follow-next').value,"krátky nadväzujúci hovor");let subs={subject:t.subject,intro:t.intro,mid:t.mid,ask:t.ask};for(let k in subs){subs[k]=subs[k].replaceAll('[názov firmy]',company).replaceAll('[téma]',topic).replaceAll('[pokrok]',progress).replaceAll('[míľnik]',milestone).replaceAll('[konkrétny ďalší krok]',next)}const out=`Predmet: ${subs.subject}\n\nDobrý deň, ${person},\n\n${subs.intro}\n\n${subs.mid}\n\n${subs.ask}\n\nS pozdravom,\n[vaše meno]`; $('follow-output').value=out;};bindCalculate('followup-calculate',run);$('follow-copy').addEventListener('click',function(){copyText($('follow-output').value,this)});run();}
function init(){initSignals();initPipeline();initRunway();initFollowup();document.querySelectorAll('a[href="/#join"],a[href="/#join"],a.button[href="/"],a[data-signup-cta]').forEach(a=>a.addEventListener('click',()=>event('tfg_signup_cta_clicked',{source_path:location.pathname,tool_slug:document.body.dataset.tool||undefined,article_slug:document.body.dataset.article||undefined})));
if(document.body.dataset.tool){event('tfg_tool_viewed',{tool_slug:document.body.dataset.tool,pathname:location.pathname});}
if(document.body.dataset.article){event('tfg_article_viewed',{article_slug:document.body.dataset.article,pathname:location.pathname});}let tracked=false;const main=document.querySelector('main');if(main)main.addEventListener('input',()=>{if(!tracked&&document.body.dataset.tool){event('tfg_tool_started',{tool_slug:document.body.dataset.tool});tracked=true}},{once:true});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
